)

// overlayHostRoot is the path containerd sees for the mock overlay on the host.
// CDI hostPaths are resolved by the runtime on the node itself, not by the agent container.
const overlayHostRoot = "/var/lib/nvml-mock"

// cdiSpec is the structure of a CDI 0.6.0 spec file.
type cdiSpec struct {
	CDIVersion     string      `json:"cdiVersion"`
	Kind           string      `json:"kind"`
	ContainerEdits *cdiEdits   `json:"containerEdits,omitempty"`
	Devices        []cdiDevice `json:"devices,omitempty"`
}

type cdiEdits struct {
	DeviceNodes []cdiDeviceNode `json:"deviceNodes,omitempty"`
	Mounts      []cdiMount      `json:"mounts,omitempty"`
	Hooks       []cdiHook       `json:"hooks,omitempty"`
	Env         []string        `json:"env,omitempty"`
}

type cdiDeviceNode struct {
	Path     string `json:"path"`
	HostPath string `json:"hostPath,omitempty"`
}

type cdiMount struct {
	HostPath      string   `json:"hostPath"`
	ContainerPath string   `json:"containerPath"`
	Options       []string `json:"options,omitempty"`
}

type cdiHook struct {
	HookName string   `json:"hookName"`
	Path     string   `json:"path"`
	Args     []string `json:"args,omitempty"`
}

type cdiDevice struct {
	Name           string   `json:"name"`
	ContainerEdits cdiEdits `json:"containerEdits"`
}

// buildNvidiaSpec returns the nvidia.com/gpu CDI spec consumed by nvidia-container-runtime.
// It includes library mounts, an ldcache hook, and per-GPU + "all" device entries.
func buildNvidiaSpec(state *agent.State) cdiSpec {
	devRoot := overlayHostRoot + "/driver/dev"

	edits := &cdiEdits{
		// Control devices are shared by every named GPU entry (per-GPU nvidia<N>
		// nodes live under devices[*].containerEdits, not here).
		DeviceNodes: []cdiDeviceNode{
			{Path: "/dev/nvidiactl", HostPath: devRoot + "/nvidiactl"},
			{Path: "/dev/nvidia-uvm", HostPath: devRoot + "/nvidia-uvm"},
			{Path: "/dev/nvidia-uvm-tools", HostPath: devRoot + "/nvidia-uvm-tools"},
		},
		Mounts: []cdiMount{
			{
				HostPath:      overlayHostRoot + "/driver/usr/lib64/libnvidia-ml.so.1",
				ContainerPath: "/usr/lib64/libnvidia-ml.so.1",
				Options:       []string{"ro", "nosuid", "nodev", "bind"},
			},
			{
				HostPath:      overlayHostRoot + "/driver/usr/bin/nvidia-smi",
				ContainerPath: "/usr/bin/nvidia-smi",
				Options:       []string{"ro", "nosuid", "nodev", "bind"},
			},
			// Bind the config directory (not just config.yaml) so atomic renames
			// by nvml-mock-ctl's overrides.yaml writes are visible inside the container.
			//
			// Writable because the container also resets through it: the mock
			// serves `nvidia-smi --gpu-reset` by clearing the device's bucket from
			// overrides.yaml, which takes an flock and rewrites the file. Read-only
			// here failed that write with EROFS exactly when the GPU had state to
			// clear, so the remediation an operator reaches for first reported
			// "GPU Reset couldn't run" on precisely the GPUs that needed it, while
			// healthy ones "succeeded" through the no-write path.
			{
				HostPath:      overlayHostRoot + "/driver/config",
				ContainerPath: "/etc/nvml-mock",
				Options:       []string{"rw", "nosuid", "nodev", "bind"},
			},
		},
		// update-ldcache rebuilds the dynamic linker cache inside the container
		// namespace so dlopen finds the bind-mounted libnvidia-ml.so.1 without
		// modifying the container image's own ld.so.conf.
		Hooks: []cdiHook{
			{
				HookName: "createContainer",
				Path:     "/usr/bin/nvidia-cdi-hook",
				Args:     []string{"nvidia-cdi-hook", "update-ldcache", "--folder", "/usr/lib64"},
			},
		},
		// None of this currently reaches a container. The toolkit resolving this
		// spec applies the mounts from the same block and drops its env (#747) —
		// unlike buildNRISpec's, which containerd resolves natively and whose env
		// does arrive. Kept because the values are correct and the mock library
		// falls back to the /etc/nvml-mock mount above when MOCK_NVML_CONFIG is
		// unset, so nothing depends on the channel working — do not add a key
		// that would.
		Env: []string{
			// void tells the container toolkit to skip its own device enumeration;
			// without it the toolkit would override our mock nodes with an empty set.
			"NVIDIA_VISIBLE_DEVICES=void",
			"MOCK_NVML_CONFIG=/etc/nvml-mock/config.yaml",
			"MOCK_NVML_OVERRIDES=/etc/nvml-mock/overrides.yaml",
		},
	}

	edits.Mounts = append(edits.Mounts, pciSysfsMounts(state)...)
	edits.Mounts = append(edits.Mounts, kernelModuleMounts()...)

	// The .so resolving fabric.state:auto runs in the consumer container, so the
	// marker dir mounts there — but only where it exists, else creation fails.
	if stateDir := state.Fabric.ManagerStateDir; stateDir != "" {
		edits.Mounts = append(edits.Mounts, cdiMount{
			HostPath:      stateDir,
			ContainerPath: stateDir,
			Options:       []string{"ro", "nosuid", "nodev", "bind"},
		})
		edits.Env = append(edits.Env, "MOCK_FABRICMANAGER_STATE_DIR="+stateDir)
	}

	allNodes := make([]cdiDeviceNode, 0, len(state.Devices))
	devices := make([]cdiDevice, 0, len(state.Devices)*2+1)
	for _, d := range state.Devices {
		node := cdiDeviceNode{
			Path:     fmt.Sprintf("/dev/nvidia%d", d.MinorNumber),
			HostPath: fmt.Sprintf("%s/nvidia%d", devRoot, d.MinorNumber),
		}
		allNodes = append(allNodes, node)
		// Index shorthand ("0".."N-1"): addressed by nvidia-container-runtime CLI.
		// The name stays the NVML index even though the node carries the minor.
		devices = append(devices, cdiDevice{
			Name:           strconv.Itoa(d.Index),
			ContainerEdits: cdiEdits{DeviceNodes: []cdiDeviceNode{node}},
		})
		// UUID entry: addressed by containerd and the device plugin allocator.
		if d.UUID != "" {
			devices = append(devices, cdiDevice{
				Name:           d.UUID,
				ContainerEdits: cdiEdits{DeviceNodes: []cdiDeviceNode{node}},
			})
		}
	}
	devices = append(devices, cdiDevice{
		Name:           "all",
		ContainerEdits: cdiEdits{DeviceNodes: allNodes},
	})
	devices = append(devices, migDevices(state, devRoot)...)

	return cdiSpec{
		CDIVersion:     "0.6.0",
		Kind:           "nvidia.com/gpu",
		ContainerEdits: edits,
		Devices:        devices,
	}
}

// migDevices returns one entry per MIG partition, named by the partition's own
// UUID.
//
// A MIG device is allocated through the same channel a whole GPU is: the device
// plugin reports the UUID NVML gave it, and the container runtime resolves that
// name here. With no entry the resolution fails outright — "unresolvable CDI
// devices nvidia.com/gpu=MIG-..." — so a pod scheduled onto a partition never
// starts even though the plugin advertised it.
//
// Each entry carries the parent's chardev, since that is where the partition's
// compute actually lives, plus the two cap nodes guarding its GPU and compute
// instance. Those are the same nodes nvidia-container-toolkit would inject
// after reading mig-minors on a real driver.
func migDevices(state *agent.State, devRoot string) []cdiDevice {
	if !state.MIG.Partitioned() {
		return nil
	}

	minorByName := migcaps.MinorByName(state.MIG.Caps())
	capNode := func(name string) (cdiDeviceNode, bool) {
		minor, ok := minorByName[name]
		if !ok {
			return cdiDeviceNode{}, false
		}
		node := fmt.Sprintf("nvidia-caps/nvidia-cap%d", minor)
		return cdiDeviceNode{Path: "/dev/" + node, HostPath: devRoot + "/" + node}, true
	}

	var devices []cdiDevice
	for _, gpu := range state.MIG.GPUs {
		parent := cdiDeviceNode{
			Path:     fmt.Sprintf("/dev/nvidia%d", gpu.Minor),
			HostPath: fmt.Sprintf("%s/nvidia%d", devRoot, gpu.Minor),
		}

		for _, gi := range gpu.GPUInstances {
			giNode, giOK := capNode(migcaps.GPUInstanceCap(gpu.Minor, gi.ID))

			for _, ci := range gi.ComputeInstances {
				ciNode, ciOK := capNode(migcaps.ComputeInstanceCap(gpu.Minor, gi.ID, ci.ID))
				// A partition with no UUID cannot be addressed, and a missing
				// cap node means the chardev was never staged: naming an
				// absent hostPath fails container creation for the whole pod,
				// so such a partition is left out rather than half-described.
				if ci.UUID == "" || !giOK || !ciOK {
					continue
				}
				devices = append(devices, cdiDevice{
					Name:           ci.UUID,
					ContainerEdits: cdiEdits{DeviceNodes: []cdiDeviceNode{parent, giNode, ciNode}},
				})
			}
		}
	}
	return devices
}

// pciSysfsMounts serves the rendered PCI tree at the kernel paths, which is the
// only way it reaches a Go consumer: libmockfs.so redirects those paths for
// libc callers, but Go's os package issues openat directly, so GFD and the DRA
// driver read the node's real /sys and find no mock GPUs (#673).
//
// The pair is indivisible — the lookup directory holds relative symlinks into
// ../../../devices/pciDDDD:BB, so serving it alone yields entries whose every
// attribute read returns ENOENT.
//
// /sys/devices goes whole, hiding the host's other device classes from served
// containers (#689): narrowing it needs mountpoints the runtime cannot create
// on a read-only sysfs, and profiles declare root complexes the node lacks.
//
// Gated on the same condition pcibus renders under, since a mount with a
// missing source fails container creation for the whole pod.
func pciSysfsMounts(state *agent.State) []cdiMount {
	if !state.HasPCITopology() {
		return nil
	}

	mounts := make([]cdiMount, 0, 2)
	// The renderer's rel-paths are the kernel paths minus the leading slash.
	for _, relPath := range []string{pcisysfs.SysDevicesRelPath, pcisysfs.PCIDevicesRelPath} {
		mounts = append(mounts, cdiMount{
			HostPath:      filepath.Join(overlayHostRoot, relPath),
			ContainerPath: "/" + relPath,
			Options:       []string{"ro", "nosuid", "nodev", "bind"},
		})
	}
	return mounts
}

// kernelModuleMounts serves the module tree and the generated lsmod at their
// kernel paths, because a Go consumer bypasses the preload shim. Ungated,
// unlike pciSysfsMounts: writeKernelModules always renders.
//
// The script goes to /usr/local/bin, which no distribution uses for lsmod.
// /usr/bin/lsmod is a symlink to the kmod multi-call binary, and a bind mount
// follows the symlink, so mounting there would replace kmod and break modprobe,
// rmmod, insmod and depmod.
func kernelModuleMounts() []cdiMount {
	return []cdiMount{
		{
			HostPath:      filepath.Join(overlayHostRoot, kmod.SysModuleRelPath),
			ContainerPath: "/" + kmod.SysModuleRelPath,
			Options:       []string{"ro", "nosuid", "nodev", "bind"},
		},
		{
			HostPath:      filepath.Join(overlayHostRoot, kmod.LsmodRelPath),
			ContainerPath: kmod.LsmodContainerPath,
			Options:       []string{"ro", "nosuid", "nodev", "bind"},
		},
	}
}

// buildNRISpec returns the nvml-mock.nvidia.com/gpu CDI spec consumed by the NRI plugin's
// cdi injection mode. No hooks or library mounts: the NRI plugin already delivers those via
// the overlay bind-mount. The module tree is the exception. No overlay mount reaches
// /sys/module. The distinct vendor (nvml-mock.nvidia.com vs nvidia.com) keeps MEP-0002's
// "exactly one source of CDI references per container" invariant observable.
func buildNRISpec(state *agent.State) cdiSpec {
	devRoot := overlayHostRoot + "/driver/dev"

	allNodes := make([]cdiDeviceNode, 0, len(state.Devices)+3)
	devices := make([]cdiDevice, 0, len(state.Devices)+1)

	for _, d := range state.Devices {
		node := cdiDeviceNode{
			Path:     fmt.Sprintf("/dev/nvidia%d", d.MinorNumber),
			HostPath: fmt.Sprintf("%s/nvidia%d", devRoot, d.MinorNumber),
		}
		devices = append(devices, cdiDevice{
			Name:           strconv.Itoa(d.Index),
			ContainerEdits: cdiEdits{DeviceNodes: []cdiDeviceNode{node}},
		})
		allNodes = append(allNodes, node)
	}

	// "all" also covers the control devices so a workload that only requests
	// "all" still gets the UVM and nvidiactl nodes it needs.
	for _, extra := range []string{"nvidiactl", "nvidia-uvm", "nvidia-uvm-tools"} {
		allNodes = append(allNodes, cdiDeviceNode{
			Path:     "/dev/" + extra,
			HostPath: devRoot + "/" + extra,
		})
	}
	devices = append(devices, cdiDevice{
		Name:           "all",
		ContainerEdits: cdiEdits{DeviceNodes: allNodes},
	})

	return cdiSpec{
		CDIVersion: "0.6.0",
		Kind:       "nvml-mock.nvidia.com/gpu",
		// NVML_MOCK_DEVICE_SOURCE makes the injection path (CDI vs raw NRI) observable
		// from inside the container — the two modes are otherwise indistinguishable.
		ContainerEdits: &cdiEdits{
			Mounts: kernelModuleMounts(),
			Env:    []string{"NVML_MOCK_DEVICE_SOURCE=cdi"},
		},
		Devices: devices,
	}
}

